CREATE OR REPLACE FUNCTION public.affiliate_dashboard_stats() RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE pid uuid; BEGIN SELECT id INTO pid FROM public.referral_profiles WHERE user_id=auth.uid(); IF pid IS NULL THEN RETURN '{}'::jsonb; END IF; RETURN (WITH m AS(SELECT coalesce(sum(greatest(commission_amount_cents-reversed_cents,0)) FILTER(WHERE status='pending'),0) pending,coalesce(sum(greatest(commission_amount_cents-reversed_cents-settled_cents,0)) FILTER(WHERE status='approved'),0) approved,coalesce(sum(settled_cents),0) paid,coalesce(sum(reversed_cents),0) reversed,coalesce(sum(commission_amount_cents-reversed_cents-settled_cents) FILTER(WHERE status IN('approved','paid') AND coalesce(payable_at,approved_at)<=now()),0)-coalesce(sum(greatest(settled_cents-(commission_amount_cents-reversed_cents),0)) FILTER(WHERE status NOT IN('approved','paid')),0) available FROM public.referral_commissions WHERE referral_profile_id=pid AND currency='usd'),p AS(SELECT coalesce(sum(amount_cents),0) requested FROM public.referral_payouts WHERE referral_profile_id=pid AND status IN('requested','under_review','approved','processing') AND currency='usd') SELECT jsonb_build_object('clicks',(SELECT count(*) FROM public.referral_clicks WHERE referral_profile_id=pid),'signups',(SELECT count(*) FROM public.referral_attributions WHERE referral_profile_id=pid),'customers',(SELECT count(*) FROM public.referral_attributions WHERE referral_profile_id=pid AND converted_at IS NOT NULL),'active_customers',0,'pending_cents',m.pending,'approved_cents',m.approved,'paid_cents',m.paid,'reversed_cents',m.reversed,'requested_cents',p.requested,'available_cents',greatest(m.available-p.requested,0)) FROM m,p); END $$;
REVOKE ALL ON FUNCTION public.affiliate_dashboard_stats() FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.affiliate_dashboard_stats() TO authenticated;
CREATE OR REPLACE FUNCTION public.save_affiliate_payout_details(_method text,_details text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL OR NOT EXISTS(SELECT 1 FROM public.referral_programs WHERE singleton AND _method=ANY(payout_methods)) OR length(trim(_details))<3 OR length(_details)>160 THEN RAISE EXCEPTION 'Valid payout details required'; END IF; UPDATE public.referral_profiles SET payout_method=_method,payout_destination_hint=trim(_details) WHERE user_id=auth.uid(); IF NOT FOUND THEN RAISE EXCEPTION 'Apply to the affiliate program first'; END IF; END $$;
REVOKE ALL ON FUNCTION public.save_affiliate_payout_details(text,text) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.save_affiliate_payout_details(text,text) TO authenticated;
REVOKE EXECUTE ON FUNCTION public.review_affiliate_payout(uuid,text,text,text),public.review_affiliate_commission(uuid,text,text) FROM anon,PUBLIC;
REVOKE EXECUTE ON FUNCTION public.affiliate_program_public() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.affiliate_program_public() TO anon,authenticated,service_role;